{
  "name": "@jasonencode/opencode-tokenwatch",
  "version": "1.0.0",
  "description": "Real-time token usage, cache analytics & performance dashboard plugin for OpenCode CLI",
  "type": "module",
  "main": "./dist/server.js",
  "types": "./dist/server.d.ts",
  "exports": {
    ".": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "tui.ts",
    "index.ts"
  ],
  "sideEffects": false,
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "tsc && node build.tui.mjs",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "plugin",
    "opencode-plugin",
    "tokens",
    "usage",
    "stats",
    "analytics",
    "tui"
  ],
  "license": "MIT",
  "author": "jasonencode",
  "contributors": [
    "TTWK"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jasonencode/opencode-tokenwatch.git"
  },
  "bugs": {
    "url": "https://github.com/jasonencode/opencode-tokenwatch/issues"
  },
  "homepage": "https://github.com/jasonencode/opencode-tokenwatch#readme",
  "devDependencies": {
    "@opencode/plugin": "2.3.2",
    "@opentui/core": "^0.9.2",
    "@opentui/solid": "^0.9.2",
    "@types/node": "^22.20.5",
    "esbuild": "^0.25.12",
    "esbuild-plugin-solid": "^0.5.0",
    "solid-js": "1.9.16",
    "typescript": "^5.9.3"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.3 <3.0.0",
    "@opentui/core": ">=0.8.4",
    "@opentui/solid": ">=0.8.4",
    "solid-js": ">=1.9.12"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  }
}

// src/server.ts
var plugin = {
  id: "opencode-tokenwatch",
  setup() {
    return () => {
    };
  }
};
var server_default = plugin;
export {
  server_default as default
};
